public class DebuggerTraceViewDiffPluginScreenShots : GhidraScreenShotGenerator, AsyncTestUtils {

	DebuggerTraceManagerService traceManager;
	DebuggerTraceViewDiffPlugin diffPlugin;
	DebuggerListingPlugin listingPlugin;
	DebuggerListingProvider listingProvider;
	ToyDBTraceBuilder tb;

	/* @Before */
	public void setUpMine()
    {
		traceManager = addPlugin(tool, typeof(DebuggerTraceManagerServicePlugin));
		diffPlugin = addPlugin(tool, typeof(DebuggerTraceViewDiffPlugin));
		listingPlugin = addPlugin(tool, typeof(DebuggerListingPlugin));
		listingProvider = waitForComponentProvider(typeof(DebuggerListingProvider));

		tb = new ToyDBTraceBuilder("tictactoe", ToyProgramBuilder._X64);
	}

	/* @After */
	public void tearDownMine() {
		tb.close();
	}

	/* @Test */
	public void testCaptureDebuggerTraceViewDiffPlugin()
    {
		long snap1, snap2;
		using (Transaction tx = tb.startTransaction())
{
			DBTraceTimeManager tm = tb.trace.getTimeManager();
			snap1 = tm.createSnapshot("Baseline").getKey();
			snap2 = tm.createSnapshot("X's first move").getKey();
			DBTraceMemoryManager mm = tb.trace.getMemoryManager();
			mm.createRegion(".data", snap1, tb.range(0x00600000, 0x0060ffff),
				TraceMemoryFlag.READ, TraceMemoryFlag.WRITE);

			ByteBuffer buf = ByteBuffer.allocate(0x1000).order(ByteOrder.LITTLE_ENDIAN);
			buf.put((byte) 'X');
			buf.putInt(3);
			buf.putInt(3);
			for (int i = 0; i < 9; i++) {
				buf.put((byte) ' ');
			}
			buf.flip();
			buf.limit(0x1000);
			mm.putBytes(snap1, tb.addr(0x00600000), buf);

			buf.put(0, (byte) 'O');
			buf.put(13, (byte) 'X');
			buf.position(0);
			buf.limit(0x1000);
			mm.putBytes(snap2, tb.addr(0x00600000), buf);
		}

		DomainFolder root = tool.getProject().getProjectData().getRootFolder();
		root.createFile("tictactoe", tb.trace, TaskMonitor.DUMMY);

		traceManager.openTrace(tb.trace);
		traceManager.activateTrace(tb.trace);
		traceManager.activateSnap(snap1);
		waitForSwing();

		waitOn(diffPlugin.startComparison(TraceSchedule.snap(snap2)));
		assertTrue(runSwing(() => diffPlugin.gotoNextDiff()));

		captureIsolatedProvider(typeof(DebuggerListingProvider), 900, 600);
	}

	/* @Test */
	public void testCaptureDebuggerTimeSelectionDialog()
    {
		TraceThread thread;
		using (Transaction tx = tb.startTransaction())
{
			DBTraceTimeManager tm = tb.trace.getTimeManager();
			thread = tb.getOrAddThread("main", 0);
			tm.createSnapshot("Break on main").setEventThread(thread);
			tm.createSnapshot("Game started").setEventThread(thread);
			tm.createSnapshot("X's moved").setEventThread(thread);
			tm.createSnapshot("O's moved").setEventThread(thread);
		}
		traceManager.openTrace(tb.trace);
		traceManager.activateThread(thread);
		waitForSwing();

		performAction(diffPlugin.actionCompare, false);
		DebuggerTimeSelectionDialog dialog =
			waitForDialogComponent(typeof(DebuggerTimeSelectionDialog));
		Swing.runNow(() => dialog.setScheduleText("2"));

		captureDialog(dialog);
	}
